var l = ["<script", ' type="application/ld+json">', "<\/script>"], p = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], h = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>SS 304 Stainless Steel Guide</span></div>'], g = ["<main", ' style="', '"><div style="', '"><span style="', '">Material Guide</span><span style="', '">June 2026 \xB7 10 min read</span><h1 style="', '">SS 304 Stainless Steel \u2014 Complete Guide to Grades, Properties, and Applications</h1><p style="', `">SS 304 is the world's most widely used stainless steel grade, accounting for over 50% of all stainless steel consumed globally. Its combination of excellent corrosion resistance, good formability, attractive appearance, and reasonable cost makes it the default choice for thousands of applications \u2014 from kitchen sinks to chemical reactors. As a leading <strong>stainless steel pipe manufacturer in India</strong> and <strong>SS pipe supplier in Vadodara</strong>, Creative Metal Industries stocks SS 304 in all product forms: pipes, plates, sheets, fittings, flanges, and bars.</p></div><h2 style="`, '">What is SS 304 Stainless Steel?</h2><p style="', '">SS 304 (also designated UNS S30400, EN 1.4301, or AISI 304) is an austenitic chromium-nickel stainless steel. The term "austenitic" refers to its face-centred cubic crystal structure, which gives it non-magnetic properties, excellent ductility, and the ability to be work-hardened but not heat-treated for strength.</p><p style="', '">The "18/8" designation that SS 304 is often called reflects its nominal composition: 18% Chromium (which forms the protective passive oxide layer) and 8% Nickel (which stabilises the austenitic structure). This combination creates a steel that resists oxidation and corrosion in a wide range of atmospheric, chemical, and food-processing environments without requiring protective coatings or painting.</p><p style="', '">First developed in the early 1900s, SS 304 has become the backbone of the stainless steel industry. Every stainless steel pipe manufacturer in India \u2014 including Creative Metal Industries \u2014 produces and stocks this grade in greater quantity than any other.</p><h2 style="', '">Chemical Composition of SS 304</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Element</th><th style="', '">SS 304</th><th style="', '">SS 304L</th><th style="', '">Role in the Alloy</th></tr></thead><tbody>', '</tbody></table></div><p style="', `">The key to SS 304's corrosion resistance is the minimum 10.5% chromium content (actually 18%+ in 304) which spontaneously forms an invisible, self-healing chromium oxide (Cr\u2082O\u2083) passive film on the surface. This film is only 1-5 nanometres thick but prevents oxygen and corrosive media from reaching the underlying iron.</p><h2 style="`, '">Mechanical Properties of SS 304</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Property</th><th style="', '">Value (Annealed Condition)</th><th style="', '">Significance</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">SS 304 cannot be hardened by heat treatment (unlike martensitic grades 410/420). It can only be strengthened by cold working \u2014 cold-drawn pipe and cold-rolled sheet have significantly higher tensile and yield strength but reduced ductility. For most piped applications, the annealed (solution treated at 1050\xB0C, water quenched) condition is standard.</p><h2 style="', '">Key Applications of SS 304</h2><div style="', '">', '</div><h2 style="', '">Welding and Fabrication Tips for SS 304</h2><p style="', '">SS 304 is highly weldable by all common processes \u2014 TIG (GTAW), MIG (GMAW), MMA (SMAW), and SAW. However, certain precautions are essential to avoid corrosion problems in service:</p><ul style="', '"><li><strong>Use 304L or ER308L filler:</strong> Low-carbon filler prevents sensitisation (carbide precipitation at 450-850\xB0C) in the heat-affected zone</li><li><strong>Minimise heat input:</strong> Austenitic SS has low thermal conductivity \u2014 excessive heat causes distortion and wider HAZ. Use stringer beads, not wide weave</li><li><strong>Back-purge with argon:</strong> The root side of TIG welds must be shielded with argon to prevent oxidation (sugaring) which creates corrosion initiation sites</li><li><strong>No preheat required:</strong> Unlike carbon and alloy steel, SS 304 should NOT be preheated. Interpass temperature should not exceed 150\xB0C</li><li><strong>Post-weld treatment:</strong> Pickle and passivate (HNO\u2083 + HF) all welds to restore the chromium oxide passive layer. Remove all heat tint colours</li><li><strong>Avoid carbon steel contamination:</strong> Use dedicated stainless steel wire brushes, grinding discs, and tools. Carbon steel particles embed in SS and cause rust spots</li></ul><h2 style="', '">Why Source SS 304 from Creative Metal Industries?</h2><p style="', `">As one of India's established <strong>stainless steel pipe manufacturers</strong> and a trusted <strong>SS pipe supplier in Vadodara</strong>, we offer distinct advantages when you source SS 304 from us:</p><div style="`, '">', '</div><h2 style="', '">Frequently Asked Questions \u2014 SS 304</h2><div style="', '">', '</div><div style="', '"><h2 style="', '">Need SS 304 Pipes, Plates or Fittings?</h2><p style="', '">Ready stock at Vadodara. Mill-direct pricing. MTC + IBR + PMI on every consignment.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/#contact" style="', '">Send Enquiry \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], f = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 Stainless Steel Pipe Manufacturer India | SS Pipe Supplier Vadodara</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], u = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], y = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], S = ["<div", ' style="', '"><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], w = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], v = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
